select genre, track, milliseconds, place
from (
  select g.genre_id, g.name as genre, t.name as track, t.milliseconds,
         row_number() over (⟦?⟧ g.genre_id order by t.milliseconds desc, t.track_id) as place
  from genre g
  join track t on t.genre_id = g.genre_id
) ranked
where place <= 2
order by genre_id, place;

mysql.code:
select genre, track, milliseconds, place
from (
  select g.genre_id, g.name as genre, t.name as track, t.milliseconds,
         row_number() over (⟦?⟧ g.genre_id order by t.milliseconds desc, t.track_id) as place
  from genre g
  join track t on t.genre_id = g.genre_id
) ranked
where place <= 2
order by genre_id, place;

